// Des: Solar trigger parse and sunrise/sunset minute stamps
// Flo: parse event + offset > compute sun times > minute stamp
// I/O: solar string + unix + lat/long > minute stamp
// ===================================================================
const std = @import("std"); const base = @import("tk-time-base.zig"); const CF = base.CF; const Local = base.Local; const daysFromCivil = base.daysFromCivil; const civiDays = base.civiDays; const locaFrom = base.locaFrom;
pub const SolarEvent = enum { sunrise, sunset }; pub const SolarSpec = struct { event: SolarEvent, offset_min: i32 }; pub const SolarError = error{ BadFormat, BadOffset };
pub fn parseSolar(sche: []const u8) SolarError!SolarSpec { const strn = std.mem.trim(u8, sche, CF.trim); var even: SolarEvent = undefined; var rest: []const u8 = ""; if (std.mem.startsWith(u8, strn, "sunrise")) { even = .sunrise; rest = strn["sunrise".len..]; } else if (std.mem.startsWith(u8, strn, "sunset")) { even = .sunset; rest = strn["sunset".len..]; } else return SolarError.BadFormat; if (rest.len == 0) return .{ .event = even, .offset_min = 0 }; if (rest[0] != '+' and rest[0] != '-') return SolarError.BadFormat; const magn = std.fmt.parseInt(i32, rest[1..], 10) catch return SolarError.BadOffset; if (magn < 0 or magn > 12 * 60) return SolarError.BadOffset; return .{ .event = even, .offset_min = if (rest[0] == '-') -magn else magn }; }
pub const SunTimes = struct { sunrise_unix: ?i64, sunset_unix: ?i64 };
pub fn sunzTime(anch: i64, lati: f64, long: f64) SunTimes { const radi = std.math.pi / 180.0; const degr = 180.0 / std.math.pi; const j197 = 2440588.0; const j200 = 2451545.0; const juli = @as(f64, @floatFromInt(anch)) / 86400.0 - 0.5 + j197; const numb = @round(juli - j200 - 0.0009 + (-long) / 360.0); const juli_star = j200 + 0.0009 + (-long) / 360.0 + numb; const mean = @mod(357.5291 + 0.98560028 * (juli_star - j200), 360.0); const mean_radi = mean * radi; const cent = 1.9148 * @sin(mean_radi) + 0.0200 * @sin(2 * mean_radi) + 0.0003 * @sin(3 * mean_radi); const lamb = @mod(mean + cent + 180 + 102.9372, 360.0); const juli_tran = juli_star + 0.0053 * @sin(mean_radi) - 0.0069 * @sin(2 * lamb * radi); const decl = std.math.asin(@sin(lamb * radi) * @sin(23.4397 * radi)) * degr; const cosh = (@sin(-0.833 * radi) - @sin(lati * radi) * @sin(decl * radi)) / (@cos(lati * radi) * @cos(decl * radi)); if (cosh > 1 or cosh < -1) return .{ .sunrise_unix = null, .sunset_unix = null }; const hang = std.math.acos(cosh) * degr; const juli_setz = j200 + 0.0009 + ((hang + (-long)) / 360.0) + numb + 0.0053 * @sin(mean_radi) - 0.0069 * @sin(2 * lamb * radi); const juli_rise = juli_tran - (juli_setz - juli_tran); return .{ .sunrise_unix = @intFromFloat(@round((juli_rise + 0.5 - j197) * 86400.0)), .sunset_unix = @intFromFloat(@round((juli_setz + 0.5 - j197) * 86400.0)) }; }
pub fn solarMinuteStamp(spec: SolarSpec, unix: i64, lati: f64, long: f64) ?i64 { const sunz = sunzTime(unix, lati, long); const targ = switch (spec.event) { .sunrise => sunz.sunrise_unix, .sunset => sunz.sunset_unix } orelse return null; const loca = locaFrom(@intCast(targ)); return loca.minute_stamp + spec.offset_min; }
